'use strict';
const $ = s => document.querySelector(s);
const messages = $('#messages');
const accounts = [
 {id:'A1042',name:'Alex Morgan',kind:'Individual investment',suffix:'1042',value:1250000,risk:'Moderate',riskLevel:2,holdings:[55,40,5]},
 {id:'A2087',name:'Jordan Lee',kind:'Retirement account',suffix:'2087',value:480000,risk:'Conservative',riskLevel:1,holdings:[30,60,10]}
];
const programs = [{name:'Guided Advisory',minimum:100000,custom:false,description:'Curated models · $100,000 minimum'}, {name:'Flexible Advisory',minimum:250000,custom:true,description:'Curated and custom models · $250,000 minimum'}];
const models = [
 {id:'MOD-101',name:'Balanced Core',risk:'Moderate',riskLevel:2,weights:[55,40,5],description:'A balanced mix of equities, fixed income, and cash.',favorite:true},
 {id:'MOD-202',name:'Income Preservation',risk:'Conservative',riskLevel:1,weights:[25,65,10],description:'A fixed-income-led mix with a smaller equity allocation.',favorite:true},
 {id:'MOD-303',name:'Global Growth',risk:'Growth',riskLevel:3,weights:[85,10,5],description:'An equity-led model for a higher risk profile.',favorite:false}
];
const reports = [{id:'SAR',name:'Strategy Analysis'}, {id:'TA',name:'Transition Analysis'}, {id:'Proposal',name:'Proposal'}, {id:'CS',name:'Client Summary'}];
let state = {account:null,program:null,model:null,validated:false,revision:0,reports:[]};
let urls = [];
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const chip = (text,action,primary=false) => `<button type="button" class="chip ${primary?'primary':''}" data-action="${action}">${text}</button>`;
function disableHistory(){messages.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);}
function add(role,html){const div=document.createElement('div');div.className=`message ${role}`;div.innerHTML=(role==='assistant'?'<div class="message-label">FOLIO ASSISTANT</div>':'')+html;messages.append(div);messages.scrollTop=messages.scrollHeight;return div;}
function user(text){disableHistory();add('user',`<p>${esc(text)}</p>`);}
function assistant(html){add('assistant',html);}
function invalidate(){state.validated=false;state.reports=[];state.revision++;}
function bar(w){return `<div class="allocation" aria-label="${w[0]}% equities, ${w[1]}% fixed income, ${w[2]}% cash">${w.map(x=>`<span style="width:${x}%"></span>`).join('')}</div><div class="legend"><span><i></i>Equity ${w[0]}%</span><span><i></i>Bonds ${w[1]}%</span><span><i></i>Cash ${w[2]}%</span></div>`;}
function update(){
 const stage=!state.account?0:!state.program?1:!state.model?2:3;
 $('#steps').innerHTML=['Account','Advisory program','Model & strategy','Validate & report'].map((x,i)=>`<li class="${i===stage?'active':i<stage?'complete':''}" ${i===stage?'aria-current="step"':''}><b>${i<stage?'✓':i+1}</b><span>${x}</span></li>`).join('');
 if(!state.account){$('#context-content').innerHTML='<div class="context-empty"><span aria-hidden="true">◈</span><h3>Your portfolio starts here</h3><p>Select an account to see your choices carried through the workflow.</p></div>';return;}
 const a=state.account;
 $('#context-content').innerHTML=`<div class="ctx-section"><button class="ctx-edit" data-action="change-account">Change</button><div class="ctx-label">ACCOUNT</div><h3>${a.name}</h3><p>${a.kind} · ••${a.suffix}</p><div class="ctx-row"><span>Portfolio value</span><strong>${money(a.value)}</strong></div><div class="ctx-row"><span>Risk profile</span><strong>${a.risk}</strong></div></div><div class="ctx-section">${state.program?'<button class="ctx-edit" data-action="change-program">Change</button>':''}<div class="ctx-label">ADVISORY PROGRAM</div><h3>${state.program?.name||'Not selected'}</h3>${state.program?'<p>'+state.program.description+'</p>':''}</div><div class="ctx-section">${state.model?'<button class="ctx-edit" data-action="change-model">Change</button>':''}<div class="ctx-label">MODEL / STRATEGY</div><h3>${esc(state.model?.name||'Not selected')}</h3>${state.model?`<p>${state.model.id} · ${state.model.risk} risk</p>${bar(state.model.weights)}`:''}</div><div class="ctx-section"><div class="ctx-label">VALIDATION</div><div class="pill ${state.validated?'good':state.model?'warn':''}">${state.validated?'✓ All demo checks passed':state.model?'Review required':'Waiting for selections'}</div>${state.reports.length?`<p style="margin-top:10px">${state.reports.length} reports generated · Revision ${state.revision}</p>`:''}</div>`;
 $('#prompt').placeholder=stage===0?'Try “Use Alex Morgan’s account”':stage===1?'Try “Select Flexible Advisory”':stage===2?'Try “Compare overlap” or “Use MOD-101”':'Try “Generate all reports” or “Change model”';
}
function showAccounts(){assistant(`<p>Let’s build a portfolio. Select a client account to get started.</p><div class="account-list">${accounts.map(a=>`<button class="choice" data-account="${a.id}"><span><strong>${a.name}</strong><small>${a.kind} · ••${a.suffix}</small></span><span><strong>${money(a.value)}</strong><small>${a.risk} risk</small></span></button>`).join('')}</div>`);}
function chooseAccount(id){const a=accounts.find(a=>a.id===id);if(!a)throw new Error('Choose a listed demo account.');user(`Use ${a.name}’s account, ending ${a.suffix}.`);state.account=a;state.program=null;state.model=null;invalidate();update();showPrograms();}
function showPrograms(){assistant(`<p><strong>${state.account.name}</strong> is selected. Choose an advisory program. The account and its inputs will carry through to each report.</p><div class="account-list">${programs.map(p=>`<button class="choice" data-program="${p.name}"><span><strong>${p.name}</strong><small>${p.description}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`);}
function chooseProgram(name){if(!state.account){assistant('<p>Select an account first.</p>');showAccounts();return;}const p=programs.find(p=>p.name===name);if(!p)throw new Error('Choose a listed advisory program.');user(`Select ${p.name}.`);state.program=p;state.model=null;invalidate();update();showMethods();}
function showMethods(){if(!state.program)return showPrograms();assistant(`<p><strong>${state.program.name}</strong> is selected. How would you like to choose a model or strategy?</p><div class="chips">${chip('Find a model','finder')}${chip('Compare overlap','overlap')}${chip('Create custom model','custom')}${chip('Use a favourite','favorites')}${chip('Enter model ID / name','lookup')}</div><p class="subtle" style="margin-top:12px">You can also type a model name or paste an ID into the conversation.</p>`);}
function modelCard(m,overlap=false){const compatible=m.riskLevel<=state.account.riskLevel;return `<button class="model-card" data-model="${m.id}"><div class="model-top"><strong>${m.name}</strong><span class="model-id">${m.id}</span></div><p>${m.description}</p><div class="model-meta"><span class="pill">${m.risk} risk</span><span class="pill ${compatible?'good':'warn'}">${compatible?'Within demo risk limit':'Exceeds account risk limit'}</span>${overlap?`<span class="pill">${overlapScore(m)}% allocation overlap</span>`:''}</div>${bar(m.weights)}</button>`;}
function overlapScore(m){return state.account.holdings.reduce((sum,w,i)=>sum+Math.min(w,m.weights[i]),0);}
function showModels(mode='finder',risk='all'){
 if(!state.program){assistant('<p>Select an account and advisory program first.</p>');return;}
 disableHistory();let list=models.filter(m=>(mode!=='favorites'||m.favorite)&&(risk==='all'||m.risk===risk));
 let intro=mode==='favorites'?'Choose a model from your saved favourites.':mode==='overlap'?'Compare your current allocation with each model. Higher overlap means a smaller change at the asset-class level.':'Choose a model to review its allocation and run validation.';
 assistant(`<p>${intro}</p>${mode==='overlap'?`<table class="mini-table"><caption class="sr-only">Current account allocation</caption><thead><tr><th>Current allocation</th><th>Equities</th><th>Fixed income</th><th>Cash</th></tr></thead><tbody><tr><td>${state.account.name}</td>${state.account.holdings.map(w=>`<td>${w}%</td>`).join('')}</tr></tbody></table><p class="subtle">Illustrative asset-class overlap: the sum of the smaller weight in each asset class. This does not measure security-level overlap.</p>`:''}${mode==='finder'?`<div class="inline-form" style="margin-bottom:12px"><label class="sr-only" for="risk-filter">Filter models by risk</label><select id="risk-filter"><option value="all">All risk profiles</option>${['Conservative','Moderate','Growth'].map(r=>`<option ${risk===r?'selected':''}>${r}</option>`).join('')}</select></div>`:''}<div class="model-grid">${list.map(m=>modelCard(m,mode==='overlap')).join('')}</div><div class="chips">${chip('Other ways to select','methods')}</div>`);
}
function chooseModel(id){if(!state.program){assistant('<p>Select an account and advisory program before choosing a model.</p>');return;}const m=models.find(m=>m.id.toLowerCase()===id.toLowerCase()||m.name.toLowerCase()===id.toLowerCase());if(!m){assistant('<p>I couldn’t find that model in the demo catalogue. Try MOD-101, MOD-202, or MOD-303.</p>');return;}user(`Use ${m.name} (${m.id}).`);state.model={...m,weights:[...m.weights]};invalidate();update();validate();}
function problems(){const p=[];if(!state.account)p.push('Select an account.');if(!state.program)p.push('Select an advisory program.');if(!state.model)p.push('Select a model.');if(p.length)return p;
 if(state.account.value<state.program.minimum)p.push(`The account does not meet the ${money(state.program.minimum)} program minimum.`);
 if(state.model.riskLevel>state.account.riskLevel)p.push(`${state.model.name} has a ${state.model.risk.toLowerCase()} risk level, above this account’s ${state.account.risk.toLowerCase()} profile.`);
 if(state.model.custom&&!state.program.custom)p.push('Custom models require Flexible Advisory.');
 if(state.model.weights.some(w=>!Number.isFinite(w)||w<0||w>100)||Math.abs(state.model.weights.reduce((a,b)=>a+b,0)-100)>.001)p.push('Model weights must be between 0% and 100% and total 100%.');
 return p;
}
function validate(){disableHistory();const errors=problems();state.validated=!errors.length;update();if(errors.length){assistant(`<div class="validation warn"><strong>Validation needs attention</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div><p>The demo blocks report generation until this is resolved. ${state.model?.riskLevel>state.account?.riskLevel?'Select a model within the account’s risk limit. Your account and program stay selected.':'Update the affected selection and run the checks again.'}</p><div class="chips">${chip('Show compatible models','compatible',true)}${state.model?.custom&&!state.program?.custom?chip('Select Flexible Advisory','flexible'):''}${chip('Choose another model','methods')}</div><p class="subtle">Validation is simulated locally. Production checks would run in backend services.</p>`);return false;}
 assistant(`<div class="validation"><strong>✓ All demo checks passed</strong><ul><li>Account meets the program minimum</li><li>Model is permitted for the program</li><li>Model risk is within the account’s demo limit</li><li>Allocation totals 100%</li></ul></div><p><strong>${esc(state.model.name)}</strong> is ready for reporting. Select the reports you need; we’ll use the account, program, and model already in this conversation.</p><div class="report-choice">${reports.map(r=>`<label><input type="checkbox" name="report" value="${r.id}" checked>${r.name}</label>`).join('')}</div><div class="chips">${chip('Generate selected reports','generate',true)}${chip('Change model','methods')}</div><p class="subtle" style="margin-top:12px">These simplified checks illustrate the workflow; they are not a suitability assessment.</p>`);return true;
}
function showCustom(){disableHistory();if(!state.program?.custom){assistant(`<div class="validation warn"><strong>Custom models need Flexible Advisory</strong>Your account remains selected. Switch programs to continue.</div><div class="chips">${chip('Select Flexible Advisory','flexible-custom',true)}${chip('Choose a curated model','finder')}</div>`);return;}
 assistant(`<p>Describe a custom allocation by setting the weights below. The demo will validate the total and derive a sample risk band before generating a model.</p><form id="custom-form"><label class="subtle" for="custom-name">Model name</label><div class="inline-form" style="margin:5px 0 13px"><input id="custom-name" name="name" value="My Balanced Model" maxlength="60" required></div><div class="custom-grid"><label>Equities (%)<input name="equity" type="number" min="0" max="100" step="1" value="50" required></label><label>Fixed income (%)<input name="bonds" type="number" min="0" max="100" step="1" value="45" required></label><label>Cash (%)<input name="cash" type="number" min="0" max="100" step="1" value="5" required></label></div><p id="custom-error" role="alert" class="subtle" style="color:#85520b;margin-top:10px"></p><button class="chip primary" type="submit" style="margin-top:10px">Generate custom model</button></form><p class="subtle" style="margin-top:12px">Demo rule: up to 30% equities = conservative; up to 65% = moderate; above 65% = growth. Weights are user-defined, not AI investment recommendations.</p>`);
}
function customModel(form){const data=new FormData(form);const name=String(data.get('name')).trim();const weights=['equity','bonds','cash'].map(k=>Number(data.get(k)));if(!name||weights.some(w=>!Number.isFinite(w)||w<0||w>100)||Math.abs(weights.reduce((a,b)=>a+b,0)-100)>.001){$('#custom-error').textContent='Enter a model name and weights between 0% and 100% that total exactly 100%.';return;}
 const riskLevel=weights[0]<=30?1:weights[0]<=65?2:3;user(`Create ${name}: ${weights[0]}% equities, ${weights[1]}% fixed income, ${weights[2]}% cash.`);state.model={id:'CUSTOM-001',name,weights,riskLevel,risk:['Conservative','Moderate','Growth'][riskLevel-1],custom:true,description:'Advisor-defined demo allocation'};invalidate();update();validate();}
function lookup(){disableHistory();assistant('<p>Enter a model ID or exact model name. You can paste a value copied from your favourites or clipboard.</p><form id="lookup-form" class="inline-form"><label class="sr-only" for="model-lookup">Model ID or name</label><input id="model-lookup" name="model" placeholder="e.g. MOD-101 or Balanced Core" maxlength="80" required><button class="chip primary" type="submit">Find model</button></form><p class="subtle" style="margin-top:10px">Demo catalogue: MOD-101 · MOD-202 · MOD-303</p>');}

function generate(ids){const errors=problems();if(errors.length){validate();return {error:errors.join(' ')};}const chosen=reports.filter(r=>ids.includes(r.id));if(!chosen.length){assistant('<p>Select at least one report to generate.</p>');return {error:'Select at least one report.'};}user(`Generate ${chosen.length===4?'all four reports':chosen.map(r=>r.name).join(', ')}.`);state.validated=true;state.reports=chosen.map(r=>r.id);const snapshot=JSON.parse(JSON.stringify({...state,generated:new Date().toLocaleString('en-GB')}));update();const links=chosen.map(r=>{const url='report.html#'+encodeURIComponent(JSON.stringify({report:r,snapshot}));return `<a class="report-link" href="${url}" target="_blank" rel="noopener"><span class="report-icon" aria-hidden="true">↗</span><strong>${r.name}</strong><small>Open report · Revision ${snapshot.revision}</small></a>`;}).join('');assistant(`<div class="validation"><strong>✓ ${chosen.length} ${chosen.length===1?'report is':'reports are'} ready</strong>Account, program, and model carried forward. No repeated inputs.</div><div class="report-grid">${links}</div><p class="report-footnote">Each link opens a fictional report in a new tab. Reports are snapshots of revision ${snapshot.revision}; changing a selection requires fresh validation and new reports.</p><div class="chips">${chip('Generate more reports','validate')}${chip('Adjust the model','methods')}${chip('Start another portfolio','change-account')}</div>`);return {status:'generated',reports:chosen.map(r=>r.id),revision:state.revision};}
function action(id){
 if(id==='change-account'){user('Change the account.');showAccounts();return;}
 if(id==='change-program'){user('Change the advisory program.');showPrograms();return;}
 if(['methods','change-model'].includes(id)){user('Choose a different model or strategy.');showMethods();return;}
 if(!state.account){showAccounts();return;}
 if(!state.program){showPrograms();return;}
 if(id==='finder'||id==='overlap'||id==='favorites'){user({finder:'Find a model.',overlap:'Compare allocation overlap.',favorites:'Show my favourite models.'}[id]);showModels(id);}
 if(id==='compatible'){user('Show models within the account’s risk limit.');assistant(`<p>These models are within ${state.account.name}’s demo risk limit. Choose one to run validation again.</p><div class="model-grid">${models.filter(m=>m.riskLevel<=state.account.riskLevel).map(m=>modelCard(m)).join('')}</div>`);}
 if(id==='custom'){user('Create a custom model.');showCustom();}
 if(id==='lookup'){user('Use a model ID or name.');lookup();}
 if(id==='flexible'||id==='flexible-custom'){chooseProgram('Flexible Advisory');if(id==='flexible-custom')showCustom();}
 if(id==='validate'){user('Review validation and select reports.');validate();}
 if(id==='generate'){const selected=[...messages.querySelectorAll('input[name="report"]:checked:not(:disabled)')].map(x=>x.value);generate(selected);}
}
function send(text){const q=text.trim();if(!q)return;const lower=q.toLowerCase();const account=accounts.find(a=>lower.includes(a.name.toLowerCase())||lower.includes(a.suffix));if(account)return chooseAccount(account.id);if(/change.*account|select.*account/.test(lower))return action('change-account');if(!state.account){user(q);assistant('<p>Please select one of the two fictional accounts to begin.</p>');showAccounts();return;}
 const program=programs.find(p=>lower.includes(p.name.toLowerCase()));if(program)return chooseProgram(program.name);if(/change.*program/.test(lower))return action('change-program');if(!state.program){user(q);showPrograms();return;}
 const model=models.find(m=>lower.includes(m.id.toLowerCase())||lower===m.name.toLowerCase()||lower.includes('use '+m.name.toLowerCase())||lower.includes('select '+m.name.toLowerCase()));if(model)return chooseModel(model.id);
 if(/overlap|compare/.test(lower))return action('overlap');if(/favou?rite/.test(lower))return action('favorites');if(/custom/.test(lower))return action('custom');if(/find.*model|show.*model/.test(lower))return action('finder');if(/change.*model|different.*model/.test(lower))return action('methods');if(/validat|check/.test(lower)){user(q);validate();return;}
 if(/report|proposal|summary|\bsar\b|\bta\b|\bcs\b/.test(lower)){const ids=[];if(/\bsar\b|strategy analysis/.test(lower))ids.push('SAR');if(/\bta\b|transition/.test(lower))ids.push('TA');if(/proposal/.test(lower))ids.push('Proposal');if(/\bcs\b|client summary/.test(lower))ids.push('CS');return generate(ids.length?ids:reports.map(r=>r.id));}
 user(q);assistant(`<p>This demo supports account and program selection, model finding, overlap comparison, custom allocations, validation, and report generation. Try one of these next steps.</p><div class="chips">${chip('Find a model','finder')}${chip('Compare overlap','overlap')}${chip('Enter model ID / name','lookup')}${state.model?chip('Validate and report','validate'):''}</div>`);
}
function reset(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];state={account:null,program:null,model:null,validated:false,revision:0,reports:[]};messages.innerHTML='';$('#prompt').value='';update();showAccounts();}
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.account)chooseAccount(el.dataset.account);else if(el.dataset.program)chooseProgram(el.dataset.program);else if(el.dataset.model)chooseModel(el.dataset.model);else if(el.dataset.action)action(el.dataset.action);});
 document.addEventListener('change',e=>{if(e.target.id==='risk-filter')showModels('finder',e.target.value);});
 document.addEventListener('submit',e=>{if(e.target.id==='custom-form'){e.preventDefault();customModel(e.target);}if(e.target.id==='lookup-form'){e.preventDefault();const value=new FormData(e.target).get('model').trim();chooseModel(value);}});
 $('#composer').onsubmit=e=>{e.preventDefault();const input=$('#prompt');const text=input.value;input.value='';send(text);};
 $('#reset').onclick=reset;
 reset();
 if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_portfolio_context',title:'Read portfolio context',description:'Read the current fictional portfolio selections, demo validation state, and generated report types.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(state))},{name:'select_demo_account',title:'Select demo account',description:'Select a fictional account and clear program, model, and validation state. The visible conversation updates.',inputSchema:{type:'object',properties:{accountId:{type:'string',enum:['A1042','A2087']}},required:['accountId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!accounts.some(a=>a.id===input.accountId))throw new Error('Unknown demo account.');chooseAccount(input.accountId);return {accountId:state.account.id,next:'Select an advisory program'};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
